# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def deleteNode(self, root: TreeNode, key: int) -> TreeNode:
        # Helper to find the node with minimum value in tree (leftmost)
        def findMin(node):
            while node.left:
                node = node.left
            return node

        if not root:
            return None

        # Traverse the tree to find the node to delete
        if key < root.val:
            root.left = self.deleteNode(root.left, key)
        elif key > root.val:
            root.right = self.deleteNode(root.right, key)
        else:
            # Node with key found
            if not root.left:
                # No left child, promote right child
                return root.right
            elif not root.right:
                # No right child, promote left child
                return root.left
            else:
                # Two children: Replace value with in-order successor
                min_larger_node = findMin(root.right)
                root.val = min_larger_node.val
                # Delete the in-order successor
                root.right = self.deleteNode(root.right, min_larger_node.val)
        return root
